def solve():
    n = int(input())
    a = list(map(int, input().split()))
    BIT = [0] * (n + 1)

    @lru_cache(None)
    def sum(i):
        res = 0
        while i:
            res += BIT[i]
            i -= i & -i
        return res

    @lru_cache(None)
    def rank(i):
        res = 0
        while i:
            res += sum(i - 1)
            i -= i & -i
        return res

    for _ in range(int(input())):
