def sieve(max_val):
    sieve = [True]*(max_val+1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(max_val**0.5)+2):
        if sieve[i]:
            for j in range(i*i, max_val+1, i):
                sieve[j] = False
    return sieve

def mexanized_array(n, k, x):
    sieve_k = sieve(x)
    candidates = set(itertools.chain.from_iterable(itertools.combinations(range(k), r) for r in range(1, min(k, n+1)))) & sieve_k
    candidates -= {0}
    if not candidates:
        return -1
    max_sum = 0
    for candidate in candidates:
        if candidate > x or (candidate+n-1) > x:
            continue
        sum_ = (candidate*(candidate-1))//2 + (x-(candidate-1))*n
        max_sum = max(max_sum, sum_)
    return max_sum

