import heapq

def init(n):
    parents = list(range(n))
    ranks = [0]*n
    return parents, ranks

def find(p):
    if p != parents[p]:
        parents[p] = find(parents[p])
    return parents[p]

def union(p, q, parents, ranks):
    root_p = find(p)
    root_q = find(q)
    if root_p == root_q:
        return
    if ranks[root_p] < ranks[root_q]:
        parents[root_p] = root_q
        ranks[root_q] += ranks[root_p]
    else:
        parents[root_q] = root_p
        ranks[root_p] += ranks[root_q]

def canSort(n, a):
    parents, ranks = init(n)
    groups = [[-1]*n, [-1]*n]
    for i in range(n):
        p = find(a[i])
        groups[a[i]%2][p] = i

    heap = [(0, 0)]
    while heap:
        cur, idx = heapq.heappop(heap)
        for j in range(1, n):
            if groups[cur%2][find(idx+j)] != -1:
                union(idx, idx+j, parents, ranks)
                groups[cur%2][find(idx+j)] = -2
                heapq.heappush(heap, (cur+1, idx+j))

    for i in range(n):
        if groups[i%2][find(i)] != -2:
            return False
    return True

def solve():
