import heapq

def generate_adjacency_list(n):
    adj_list = [[] for _ in range(n)]
    for i in range(1, n):
        for j in range(i + 1, n + 1):
            if i + j <= n:
                adj_list[i - 1].append((i + j - n, j))
                adj_list[j - 1].append((i, i + j - n))
    return adj_list

def topological_sort(adj_list):
    in_degree = [0] * len(adj_list)
    for node, neighbors in enumerate(adj_list):
        for neighbor in neighbors:
            in_degree[neighbor[0]] += 1
    q = [node for node, degree in enumerate(in_degree) if degree == 0]
    result = []
    heapq.heapify(q)

    while q:
        u = heapq.heappop(q)
        result.append(u)
        for v, _ in adj_list[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(q, v)

    return result

def solve(n):
    adj_list = generate_adjacency_list(n)
    permutation = topological_sort(adj_list)
    return permutation

