        if depth == n:
            return 1
        count = 0
        for neighbor in graph[curr] if curr in graph else []:
            if neighbor not in visited:
                visited.add(neighbor)
                count += dfs(visited, neighbor, depth + 1)
        return count

    def bfs(visited, queue):
        while queue:
            curr = queue.popleft()
            if curr not in visited:
                visited.add(curr)
                if len(visited) == n:
                    return 1
                for neighbor in graph[curr] if curr in graph else []:
                    queue.append(neighbor)
        return 0

