import sys
import heapq

def dijkstra(graph, start):
    dist = {letter: float('inf') for letter in graph}
    dist[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        d, current = heapq.heappop(priority_queue)

        if dist[current] < d:
