Here is a Python solution using Depth-First Search (DFS) with memoization to avoid redundant computations. The solution adheres to the given constraints.

```python
from collections import defaultdict
from itertools import chain, count
import sys

input = sys.stdin.readline

def solve():
    n, m = map(int, input().split())
    if n == 1 or m == 1:
        return 1

    memo = defaultdict(lambda: float('inf'))
    memo[(1, 1)] = 0

    def dfs(x, y):
        if x > n or y > m:
            return float('inf')

        if (x, y) in memo:
            return memo[(x, y)]

        cost = float('inf')
        if x < n:
            cost = min(cost, dfs(x + 1, y))
        if y < m:
            cost = min(cost, dfs(x, y + 1))
        memo[(x, y)] = cost + x * m + y
        return cost + x * m + y

    return dfs(2, 1)

T = int(input().strip())
for _ in range(T):
    print(solve())
